import os
import gzip
import base64
import subprocess

PLIST_XML = """<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleExecutable</key>
    <string>MarketplaceKit</string>
    <key>CFBundleIdentifier</key>
    <string>com.apple.MarketplaceKit</string>
    <key>CFBundlePackageType</key>
    <string>FMWK</string>
    <key>CFBundleShortVersionString</key>
    <string>1.0</string>
    <key>CFBundleVersion</key>
    <string>1</string>
</dict>
</plist>
"""

MARKETPLACE_KIT_GZ_B64 = """"""

def apply(app_bundle):
    """Embeds MarketplaceKit.framework and updates binary load command."""
    fw_dir = os.path.join(app_bundle, "Frameworks", "MarketplaceKit.framework")
    os.makedirs(fw_dir, exist_ok=True)
    
    bin_path = os.path.join(fw_dir, "MarketplaceKit")
    with open(bin_path, "wb") as f:
        f.write(gzip.decompress(base64.b64decode(MARKETPLACE_KIT_GZ_B64)))
    os.chmod(bin_path, 0o755)
    
    plist_path = os.path.join(fw_dir, "Info.plist")
    with open(plist_path, "w") as f:
        f.write(PLIST_XML)
        
    main_bin = os.path.join(app_bundle, os.path.splitext(os.path.basename(app_bundle))[0])
    if os.path.isfile(main_bin):
        subprocess.run([
            "install_name_tool", "-change",
            "/System/Library/Frameworks/MarketplaceKit.framework/MarketplaceKit",
            "@rpath/MarketplaceKit.framework/MarketplaceKit",
            main_bin
        ], capture_output=True)
